<?php
require_once 'config/functions.php';
$cart=$_SESSION['cart']??[];$items=[];$total=0;
if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',', $ids);$res=$conn->query("SELECT * FROM produk WHERE id_produk IN ($in)");while($p=$res->fetch_assoc()){$qty=(int)$cart[$p['id_produk']];if($qty>$p['stok']){$qty=(int)$p['stok'];$_SESSION['cart'][$p['id_produk']]=$qty;}if($qty<1)continue;$p['jumlah']=$qty;$p['subtotal']=$qty*(float)$p['harga'];$total+=$p['subtotal'];$items[]=$p;}}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['jumlah']??[] as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$id]);else{$_SESSION['cart'][$id]=min($qty,999);}}flash('Keranjang diperbarui.');redirect('keranjang.php');}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keranjang - MarketKu</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark navbar-market"><div class="container"><a class="navbar-brand" href="index.php">MarketKu</a><a class="btn btn-light btn-sm" href="index.php">Lanjut Belanja</a></div></nav><main class="container py-4"><?php show_flash();?><h2 class="fw-bold mb-4">Keranjang Belanja</h2><?php if(!$items):?><div class="alert alert-info">Keranjang masih kosong. <a href="index.php">Cari produk</a></div><?php else:?><form method="post"><div class="card content-card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th>Harga</th><th style="width:130px">Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><?=e($p['nama_produk'])?></td><td><?=rupiah($p['harga'])?></td><td><input class="form-control" type="number" min="0" max="<?=$p['stok']?>" name="jumlah[<?=$p['id_produk']?>]" value="<?=$p['jumlah']?>"></td><td><?=rupiah($p['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex flex-wrap justify-content-between align-items-center"><button class="btn btn-outline-primary">Perbarui Keranjang</button><h4 class="price">Total: <?=rupiah($total)?></h4></div></div></form><div class="text-end mt-3"><a class="btn btn-primary btn-lg" href="checkout.php">Lanjut Checkout</a></div><?php endif;?></main></body></html>
